pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timeJump) public {
        // timeJump must be positive to ensure block.timestamp > pastBlockTime
        vm.assume(timeJump > 0);

        // Get initial pastBlockTime
        uint256 prev = c.pastBlockTime();

        // Warp to a time after the last recorded timestamp
        vm.warp(block.timestamp + timeJump);

        // Provide exactly 10 ether
        vm.deal(address(this), 10 ether);

        // Call fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Assert the call succeeded (the require checks are satisfied)
        assertTrue(success);

        // The general rule: pastBlockTime must have increased
        assertTrue(c.pastBlockTime() > prev);
    }
}

