import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _blockNumber, uint256 _timestamp) public {
        // Use block.number and block.timestamp as parameters; assume they are reasonable
        vm.assume(_blockNumber % 15 == 0); // only when block.number % 15 == 0 does the transfer happen
        _timestamp = bound(_timestamp, 1, type(uint256).max);

        // Set the block context
        vm.warp(_timestamp);
        vm.roll(_blockNumber);

        // Fund the contract with at least 10 ether to satisfy the require in fallback
        vm.deal(address(c), 10 ether);

        // Make the call that triggers the fallback
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success);

        // After a transfer, pastBlockTime must be updated (= timestamp)
        // In the buggy version, pastBlockTime remains old (0 initially), so rule breaks
        assertTrue(c.pastBlockTime() == _timestamp);
    }
}

