pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 val, uint256 blockNumberOffset) public {
        // Ensure msg.value is exactly 10 ether
        vm.assume(val == 10 ether);
        // Ensure block.timestamp > pastBlockTime (initially 0)
        vm.warp(block.timestamp + 1);
        // Set block number to a multiple of 15 to trigger the if-block
        uint256 targetBlock = (block.number / 15 + 1) * 15 + (blockNumberOffset % 15);
        vm.roll(targetBlock);
        uint256 balanceBefore = address(c).balance;
        // Fund contract with some ether so it has a balance to transfer
        vm.deal(address(c), 10 ether + 5 ether);
        // Call fallback with 10 ether
        (bool success, ) = address(c).call{value: val}("");
        assertTrue(success, "Fallback should succeed");
        // In reference, balance decreases by full balance (0 after transfer).
        // In mutant, balance decreases by 1 ether, leaving remainder.
        // General rule: balance after call is less than balance before.
        assertTrue(address(c).balance < balanceBefore + 10 ether);
    }
}

