pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint128 value1, uint256 blockOffset) public {
        // Restrict value1 to 10 ether to pass require(msg.value == 10 ether)
        vm.assume(value1 == 10 ether);

        // Ensure blockOffset doesn't overflow and gives us two different blocks
        vm.assume(blockOffset < type(uint256).max - 15);

        // First call: set pastBlockTime and possibly trigger transfer (if block.number % 15 == 0)
        vm.warp(100);
        vm.roll(block.number + blockOffset);

        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "First call failed");

        // Record balance after first call
        uint256 balanceAfterFirst = address(c).balance;

        // Second call: must be at a later time and possible different block
        vm.warp(block.timestamp + 1);
        vm.roll(block.number + 1);

        (bool success2, ) = address(c).call{value: 10 ether}("");
        require(success2, "Second call failed");

        uint256 balanceAfterSecond = address(c).balance;

        // General rule: if the first call triggered the if-block (balance dropped), 
        // then after two calls the balance should be zero in reference (all sent)
        // and non-zero in mutant (only 1 ether sent per call)
        // Specifically: balanceAfterFirst == 0 implies balanceAfterSecond == 0 (reference) 
        // but balanceAfterSecond > 0 (mutant)
        bool firstCallTriggered = (balanceAfterFirst < 10 ether);
        if (firstCallTriggered) {
            // In reference, all balance was sent; second call adds 10 ether, then if triggered sends all again
            // In mutant, first sent 1 ether, second adds 10 ether, then sends 1 ether again
            // The rule: after both calls, the reference always has 0 if both triggered, mutant has 8 ether
            assertTrue(balanceAfterSecond == 0 || balanceAfterSecond == 8 ether);
        } else {
            // If neither triggered, both balances are 20 ether
            assertTrue(balanceAfterSecond == 20 ether);
        }
    }
}

