pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint128 value, uint256 blockOffset) public {
        vm.assume(value > 10 ether); // ensure we have enough ETH
        vm.assume(blockOffset < 15); // to control block.number % 15

        // Fund the contract
        vm.deal(address(c), value);
        uint256 balanceBefore = address(c).balance;

        // Set block.number to a multiple of 15
        vm.roll((block.number / 15 + 1) * 15 + blockOffset);

        // Make a fallback call with exactly 10 ether
        vm.deal(address(this), 10 ether);
        (bool success,) = address(c).call{value: 10 ether}("");

        // The transfer happens when block.number % 15 == 0 (i.e., blockOffset == 0)
        if (blockOffset == 0 && success) {
            uint256 balanceAfter = address(c).balance;
            // In reference: balanceAfter == balanceBefore (full balance sent out)
            // In mutant: balanceAfter == balanceBefore - 1 ether (only 1 ether sent)
            assertTrue(balanceAfter == balanceBefore);
        } else {
            assertTrue(success);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 timeJump, uint256 blockNumber) public {
        // Bound and assume so the reference's require(block.timestamp > pastBlockTime) passes
        vm.assume(blockNumber <= type(uint256).max / 15 * 15); // avoid overflow in our check
        vm.assume(timeJump > 0);
        // Set block timestamp and number so that the fallback call will satisfy conditions
        vm.warp(block.timestamp + timeJump);
        // We need block.number % 15 == 0 to trigger the transfer
        // We can't directly set block.number, but we can use vm.roll to set a number satisfying condition
        // The next available block number after deployment is around 0; we need a multiple of 15 that is > 0
        vm.roll(blockNumber * 15 + 15); // ensures block.number % 15 == 0

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Deal 10 ether to the caller and make the fallback call
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // We require the call succeeded; if it reverts, skip this case
        if (!success) return;

        uint256 balanceAfter = address(c).balance;
        // The reference sends the entire balance, so balanceAfter should be 0
        // The mutant sends only 1 ether, so balanceAfter would be balanceBefore - 1 ether
        assertTrue(balanceAfter == 0, "Balance after should be 0 for reference");
    }
}
